        <label htmlFor="message">Message</label>
        <input
          id="message"
          type="text"
          name="message"
          required
          style={{ padding: "0.5rem", fontSize: "1rem" }}
        />
        <button type="submit" style={{ padding: "0.5rem 1rem", fontSize: "1rem" }}>
          Submit
        </button>
      </form>

      <p style={{ marginTop: "1.5rem" }}>
        <a href="/messages">View submitted messages (JSON)</a>
      </p>
    </main>
  );
};
